class default_bm25:
    def __init__(self):
        self.k1 = 1.2
        self.b = 0.75

    def __call__(self, doc, query):
        # Calculate BM25 similarity
        idf = self._idf(doc, query)
        tfidf = self._tfidf(doc, query)
        bm25 = self._bm25(tfidf, idf)
        return bm25

    def _idf(self, doc, query):
        # Calculate IDF (Inverse Document Frequency)
        idf = {}
        for term in query:
            idf[term] = np.log((len(doc) + 1) / (self._doc_freq(doc, term) + 1))
        return idf

    def _tfidf(self, doc, query):
        # Calculate TF-IDF (Term Frequency-Inverse Document Frequency)
        tfidf = {}
        for term in query:
            tfidf[term] = self._tf(doc, term) * self._idf(doc, term)
        return tfidf

    def _bm25(self, tfidf, idf):
        # Calculate BM25 similarity
        bm25 = 0
        for term, weight in tfidf.items():
            bm25 += weight * idf[term]
        return bm25

    def _doc_freq(self, doc, term):
        # Calculate document frequency
        return sum(1 for d in doc if term in d)

    def _tf(self, doc, term):
        # Calculate term frequency
        return doc.count(term) / len(doc)


